it('P1: người tạo không được tự phê duyệt dù số tiền trong hạn mức của chính mình', async () => {
    const dx = await taoDeXuat('HM-2026-8001', 100_000_000, 'lan');

    const res = await duyet(dx.id, 'lan');

    expect(res.statusCode).toBe(403);
    expect(res.body).toContain('Người tạo đề xuất không được tự phê duyệt');

    const sau = await layDeXuat(dx.id);
    expect(sau.trang_thai).toBe('cho_duyet');
    expect(sau.nguoi_duyet).toBeFalsy();
  });

it('P2: người duyệt khác người tạo nhưng vượt hạn mức vai vẫn bị chặn', async () => {
    const dx = await taoDeXuat('HM-2026-8002', 600_000_000, 'hung');

    const res = await duyet(dx.id, 'lan');

    expect(res.statusCode).toBe(403);
    expect(res.body).toContain('vượt hạn mức');
    expect(res.body).toContain('500.000.000');

    const sau = await layDeXuat(dx.id);
    expect(sau.trang_thai).toBe('cho_duyet');
    expect(sau.nguoi_duyet).toBeFalsy();
  });

